@startuml

class GameArea {
  + name : string
}

class GameElement {
  + x : long
  + y : long
}

class Shape extends GameElement {}

class Object extends GameElement {}

class Opponent extends GameElement {}

class Enemy extends Opponent {
  + lives : int
  + kill()
}

class GamePiece {}

GameArea "1" *-- "1..*" GameElement
GameArea "1" *-- "1..2" GamePiece
GameArea "1" --> "1 boss" Opponent
Shape "*" -- "*" Shape : is_connected_to

@enduml

